/**
 * sha256.mjs — SHA-256 implemented from scratch, exactly per FIPS 180-4.
 *
 * There is deliberately no platform hashing anywhere in this file (or anywhere
 * else in this library): every output byte is produced by the plain-JavaScript
 * compression function below, so the whole port is provably self-contained.
 *
 * Reference: NIST FIPS PUB 180-4, section 6.2 ("SHA-256").
 *
 *   - words are 32 bits, big-endian
 *   - the message is padded with 0x80, then zero bytes, then the 64-bit
 *     big-endian bit length, so the total length is a multiple of 64 bytes
 *   - each 64-byte block expands to a 64-word message schedule W[0..63] and is
 *     mixed into the running state with 64 rounds of the compression function
 *
 * All intermediate arithmetic is coerced back to unsigned 32-bit with `>>> 0`.
 * Additions are performed on doubles first: a sum of five 32-bit values is at
 * most 5 * (2^32 - 1) < 2^53, so it is still exact before the truncation.
 *
 * Known-answer self-checks (FIPS 180-4 / NESSIE vectors):
 *   ""                                     -> e3b0c442...7852b855
 *   "abc"                                  -> ba7816bf...f20015ad
 *   "abcdbcde...nopnopq" (56 bytes, 448 b) -> 248d6a61...19db06c1
 */

import { utf8Encode } from './bytes.mjs';

/** Block size of SHA-256 in bytes (512 bits). */
export const SHA256_BLOCK_SIZE = 64;

/** Digest size of SHA-256 in bytes (256 bits). */
export const SHA256_DIGEST_SIZE = 32;

/** Byte offset inside the final block where the 64-bit bit length starts. */
const LENGTH_FIELD_SIZE = 8;

/**
 * A message needs its own extra block when the 0x80 terminator plus the 8-byte
 * length field no longer fit in the tail block, i.e. when the tail is 56 bytes
 * or longer.
 */
const MAX_TAIL_WITHOUT_EXTRA_BLOCK = SHA256_BLOCK_SIZE - LENGTH_FIELD_SIZE; // 56

/**
 * Divisor that turns a byte length into the high word of the 64-bit bit length:
 * (length * 8) / 2^32 === length / 2^29 === length / 536870912.
 *
 * Doing the division instead of the multiplication keeps the high word exact for
 * any length JavaScript can address, so a message larger than 512 MiB (where the
 * bit count no longer fits in 32 bits) still gets the correct padding.
 */
const BYTES_PER_HIGH_BIT_WORD = 536870912; // 2 ** 29

/**
 * FIPS 180-4 section 4.2.2: the first 32 bits of the fractional parts of the
 * cube roots of the first 64 primes.
 */
const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
  0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
  0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
  0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
  0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
  0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
  0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
  0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
  0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

/**
 * FIPS 180-4 section 5.3.3: the initial hash value H(0) — the first 32 bits of
 * the fractional parts of the square roots of the first 8 primes.
 */
const INITIAL_HASH = new Uint32Array([
  0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
  0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19,
]);

/**
 * ROTR^n(x): circular right shift of a 32-bit word (FIPS 180-4, section 3.2).
 *
 * @param {number} x 32-bit word
 * @param {number} n rotation amount, 1..31
 * @returns {number} the rotated word as an unsigned 32-bit value
 */
function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

/**
 * Ch(x, y, z) = (x AND y) XOR (NOT x AND z) — pick bits of y where x is set,
 * bits of z where x is clear.
 *
 * @param {number} x
 * @param {number} y
 * @param {number} z
 * @returns {number} unsigned 32-bit result
 */
function ch(x, y, z) {
  return ((x & y) ^ (~x & z)) >>> 0;
}

/**
 * Maj(x, y, z) = (x AND y) XOR (x AND z) XOR (y AND z) — bitwise majority vote.
 *
 * @param {number} x
 * @param {number} y
 * @param {number} z
 * @returns {number} unsigned 32-bit result
 */
function maj(x, y, z) {
  return ((x & y) ^ (x & z) ^ (y & z)) >>> 0;
}

/**
 * Big sigma 0: ROTR^2(x) XOR ROTR^13(x) XOR ROTR^22(x). Used on `a` in the
 * compression loop.
 *
 * @param {number} x
 * @returns {number} unsigned 32-bit result
 */
function bigSigma0(x) {
  return (rotr(x, 2) ^ rotr(x, 13) ^ rotr(x, 22)) >>> 0;
}

/**
 * Big sigma 1: ROTR^6(x) XOR ROTR^11(x) XOR ROTR^25(x). Used on `e` in the
 * compression loop.
 *
 * @param {number} x
 * @returns {number} unsigned 32-bit result
 */
function bigSigma1(x) {
  return (rotr(x, 6) ^ rotr(x, 11) ^ rotr(x, 25)) >>> 0;
}

/**
 * Small sigma 0: ROTR^7(x) XOR ROTR^18(x) XOR SHR^3(x). Used when expanding the
 * message schedule.
 *
 * @param {number} x
 * @returns {number} unsigned 32-bit result
 */
function smallSigma0(x) {
  return (rotr(x, 7) ^ rotr(x, 18) ^ (x >>> 3)) >>> 0;
}

/**
 * Small sigma 1: ROTR^17(x) XOR ROTR^19(x) XOR SHR^10(x). Used when expanding
 * the message schedule.
 *
 * @param {number} x
 * @returns {number} unsigned 32-bit result
 */
function smallSigma1(x) {
  return (rotr(x, 17) ^ rotr(x, 19) ^ (x >>> 10)) >>> 0;
}

/**
 * Coerce an input into a Uint8Array of message bytes.
 *
 * Strings are UTF-8 encoded first (Python's hashlib refuses str outright, but
 * every caller in this library that starts from text wants UTF-8, so doing it
 * here removes a foot-gun without changing any digest).
 *
 * @param {Uint8Array|ArrayBuffer|number[]|string} input
 * @returns {Uint8Array}
 */
function toMessageBytes(input) {
  if (input instanceof Uint8Array) {
    return input;
  }
  if (typeof input === 'string') {
    return utf8Encode(input);
  }
  if (input instanceof ArrayBuffer) {
    return new Uint8Array(input);
  }
  if (Array.isArray(input)) {
    return new Uint8Array(input);
  }
  throw new TypeError('sha256 expects a Uint8Array or a string');
}

/**
 * Write an unsigned 32-bit value into `target` big-endian (most significant byte
 * first).
 *
 * @param {Uint8Array} target destination buffer
 * @param {number} offset index of the most significant byte
 * @param {number} word value to store; only its low 32 bits are used
 * @returns {void}
 */
function writeUint32BE(target, offset, word) {
  const value = word >>> 0;
  target[offset] = (value >>> 24) & 0xff;
  target[offset + 1] = (value >>> 16) & 0xff;
  target[offset + 2] = (value >>> 8) & 0xff;
  target[offset + 3] = value & 0xff;
}

/**
 * Hash one 64-byte block into the running state (FIPS 180-4 section 6.2.2).
 *
 * `state` and `schedule` are reused across blocks so a long message does not
 * allocate per block.
 *
 * @param {Uint32Array} state 8 words of running hash value, updated in place
 * @param {Uint32Array} schedule scratch space for W[0..63], overwritten
 * @param {Uint8Array} block buffer holding the block
 * @param {number} offset byte offset of the block inside `block`
 * @returns {void}
 */
function compressBlock(state, schedule, block, offset) {
  // Step 1a: the first 16 words are the block itself, read big-endian.
  for (let t = 0; t < 16; t += 1) {
    const i = offset + t * 4;
    schedule[t] = (
      ((block[i] << 24) | (block[i + 1] << 16) | (block[i + 2] << 8) | block[i + 3]) >>> 0
    );
  }

  // Step 1b: expand to 64 words.
  // W[t] = sigma1(W[t-2]) + W[t-7] + sigma0(W[t-15]) + W[t-16]
  for (let t = 16; t < 64; t += 1) {
    const s0 = smallSigma0(schedule[t - 15]);
    const s1 = smallSigma1(schedule[t - 2]);
    schedule[t] = (s1 + schedule[t - 7] + s0 + schedule[t - 16]) >>> 0;
  }

  // Step 2: initialise the eight working variables with the current hash value.
  let a = state[0];
  let b = state[1];
  let c = state[2];
  let d = state[3];
  let e = state[4];
  let f = state[5];
  let g = state[6];
  let h = state[7];

  // Step 3: 64 rounds.
  for (let t = 0; t < 64; t += 1) {
    const t1 = (h + bigSigma1(e) + ch(e, f, g) + K[t] + schedule[t]) >>> 0;
    const t2 = (bigSigma0(a) + maj(a, b, c)) >>> 0;

    h = g;
    g = f;
    f = e;
    e = (d + t1) >>> 0;
    d = c;
    c = b;
    b = a;
    a = (t1 + t2) >>> 0;
  }

  // Step 4: add the working variables back into the hash value.
  state[0] = (state[0] + a) >>> 0;
  state[1] = (state[1] + b) >>> 0;
  state[2] = (state[2] + c) >>> 0;
  state[3] = (state[3] + d) >>> 0;
  state[4] = (state[4] + e) >>> 0;
  state[5] = (state[5] + f) >>> 0;
  state[6] = (state[6] + g) >>> 0;
  state[7] = (state[7] + h) >>> 0;
}

/**
 * Build the padded tail: the leftover bytes that did not fill a whole block,
 * followed by 0x80, zero padding, and the 64-bit big-endian bit length.
 *
 * The result is always one or two whole blocks (128 bytes when the leftover is
 * 56..63 bytes long, because the terminator plus the length field no longer fit
 * alongside it).
 *
 * @param {Uint8Array} bytes the full message
 * @param {number} tailStart byte offset where the leftover starts
 * @returns {Uint8Array} 64 or 128 bytes of padded tail
 */
function buildPaddedTail(bytes, tailStart) {
  const tailLength = bytes.length - tailStart;
  const paddedSize = tailLength < MAX_TAIL_WITHOUT_EXTRA_BLOCK
    ? SHA256_BLOCK_SIZE
    : SHA256_BLOCK_SIZE * 2;
  const tail = new Uint8Array(paddedSize);

  // Copy the leftover message bytes, then append the single 1 bit as 0x80.
  // The rest of the buffer is already zero.
  tail.set(bytes.subarray(tailStart), 0);
  tail[tailLength] = 0x80;

  // The message length in *bits* as a big-endian 64-bit integer. Math.floor on
  // the byte count keeps the high word exact even past 2^32 bits (512 MiB), and
  // `>>> 0` reduces the low word modulo 2^32 as required.
  const bitLengthHigh = Math.floor(bytes.length / BYTES_PER_HIGH_BIT_WORD);
  const bitLengthLow = (bytes.length * 8) >>> 0;
  writeUint32BE(tail, paddedSize - 8, bitLengthHigh);
  writeUint32BE(tail, paddedSize - 4, bitLengthLow);

  return tail;
}

/**
 * Compute the SHA-256 digest of a message.
 *
 * Correct for any input length, including the awkward 55/56/63/64-byte padding
 * boundaries and the empty message.
 *
 * @param {Uint8Array|ArrayBuffer|number[]|string} input message bytes (a string
 *   is UTF-8 encoded first)
 * @returns {Uint8Array} the 32-byte digest, most significant byte first
 */
export function sha256(input) {
  const bytes = toMessageBytes(input);

  // Fresh copy of H(0) per call: the function is pure and re-entrant.
  const state = new Uint32Array(INITIAL_HASH);
  const schedule = new Uint32Array(64);

  // Hash every complete block straight out of the input, without copying it.
  const wholeBlocks = Math.floor(bytes.length / SHA256_BLOCK_SIZE);
  for (let blockIndex = 0; blockIndex < wholeBlocks; blockIndex += 1) {
    compressBlock(state, schedule, bytes, blockIndex * SHA256_BLOCK_SIZE);
  }

  // Then hash the padded tail (one or two blocks).
  const tail = buildPaddedTail(bytes, wholeBlocks * SHA256_BLOCK_SIZE);
  for (let offset = 0; offset < tail.length; offset += SHA256_BLOCK_SIZE) {
    compressBlock(state, schedule, tail, offset);
  }

  // Serialise the eight state words big-endian.
  const digest = new Uint8Array(SHA256_DIGEST_SIZE);
  for (let i = 0; i < 8; i += 1) {
    writeUint32BE(digest, i * 4, state[i]);
  }
  return digest;
}

/**
 * Scratch verification for /output/lib/sha256.mjs — known-answer tests only,
 * no platform hashing used as an oracle.
 */

import { sha256, SHA256_BLOCK_SIZE, SHA256_DIGEST_SIZE } from '/output/lib/sha256.mjs';
import { utf8Encode } from '/output/lib/bytes.mjs';
import { hmacSha256 } from '/output/lib/hmac.mjs';

