const repeatByte = (byte, n) => new Uint8Array(n).fill(byte);

let failures = 0;
function check(label, actual, expected) {
  if (actual === expected) {
    console.log(`ok   ${label}`);
  } else {
    failures += 1;
    console.log(`FAIL ${label}\n  actual   ${actual}\n  expected ${expected}`);
  }
}

// ---- FIPS / NESSIE string vectors -------------------------------------------
const stringVectors = [
  ['empty (0 bytes)', '', 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'],
  ['"a" (1)', 'a', 'ca978112ca1bbdcafac231b39a23dc4da786eff8147c4e72b9807785afee48bb'],
  ['"abc" (3)', 'abc', 'ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad'],
  ['"message digest" (14)', 'message digest', 'f7846f55cf23e14eebeab5b4e1550cad5b509e3348fbc4efa3a1413d393cb650'],
